from __future__ import annotations
from decimal import Decimal, InvalidOperation

from probes.phone_verification_provider import OperationState as ProviderOperationState, ProviderApiError, Service
from probes.viotp_api import ViOtpApi

from ..eligibility_phone import AcquisitionResult


class ViOTPProviderAdapter:
    """ViOTP product adapter; orchestration/retry policy remains in product service."""

    def __init__(self, api: ViOtpApi | None = None):
        self.api = api or ViOtpApi.from_environment()

    def resolve_youtube_service(self) -> Service | None:
        return self.api.resolve_youtube_service("vn")

    def resolve_network(self, name: str) -> Service | None:
        return self.api.resolve_network(name)

    def acquire(self, service: Service, network: str) -> AcquisitionResult:
        try:
            price = Decimal(str(service.price))
            if not price.is_finite() or price <= 0 or price > 3000:
                return AcquisitionResult("PRICE_LIMIT")
        except (InvalidOperation, ValueError):
            return AcquisitionResult("PRICE_LIMIT")
        try:
            return AcquisitionResult(
                "ACQUIRED",
                self.api.acquire_number(service, country="vn", network=network),
            )
        except ProviderApiError as error:
            if error.state is ProviderOperationState.NO_STOCK:
                return AcquisitionResult("NO_STOCK")
            return AcquisitionResult("AMBIGUOUS")

    def wait_for_otp(self, request_id: str):
        return self.api.wait_for_otp(request_id)

